var rootDevice = instance.RootDevice;
var rootId = rootDevice.GlobalId;

if (nodeId == rootId)
    return rootDevice;

if (nodeId.StartsWith(rootId + "/", StringComparison.Ordinal))
{
    var relative = nodeId.Substring(rootId.Length + 1);
    Component found = null;
    try
    {
        found = rootDevice.FindComponent(relative);
    }
    catch (OpenDaqException)
    {
        found = null;
    }
    if (found is not null)
        return found;
}

if (component.CanCastTo<Channel>())
    return "channel";
if (component.CanCastTo<Device>())
    return "device";
if (component.CanCastTo<FunctionBlock>())
    return "function_block";
if (component.CanCastTo<Signal>())
    return "signal";
// Everything else -- folders and plain components such as Synchronization
// -- is reported as a folder; the contract's kind set has no other
// container.
return "folder";

if (!component.CanCastTo<Device>())
    throw new WireError(WireErrorCode.Unsupported,
        $"component \"{nodeId}\" is a {KindOf(component)} and not a device, so {wireMethod} has nothing to " +
        "act on; openDAQ puts lock/unlock and the operation modes on IDevice");
var device = component.Cast<Device>();

// IDevice.lock() takes no arguments in the .NET binding: openDAQ
// resolves the user from the instance's authentication provider, and
// locks every child device of this one as well. IDevice.locked is
// what reads the state back, and it is already on every Node.
device.Lock();

// IDevice.unlock() takes no arguments in the .NET binding and
// refuses with OPENDAQ_ERR_ACCESSDENIED when the lock belongs to
// another user; that refusal is what read_only carries back.
device.Unlock();

device.lock.cpp:
// openDAQ has no "kind" attribute: a component's kind is whichever of these
// interfaces it can be cast to, and the order matters because a Channel is
// also a FunctionBlock and a Device is also a Folder.
if (component.asPtrOrNull<IChannel>().assigned())
    return "channel";
if (component.asPtrOrNull<IDevice>().assigned())
    return "device";
if (component.asPtrOrNull<IFunctionBlock>().assigned())
    return "function_block";
if (component.asPtrOrNull<ISignal>().assigned())
    return "signal";
// Everything else -- folders and plain components such as Synchronization --
// is reported as a folder; the contract's kind set has no other container.
return "folder";

// openDAQ declares lock, unlock and the operation modes on IDevice, not
// on IComponent, so the component has to be taken through its IDevice
// facet before any of them can be called. A component that does not
// carry that facet is not a device -- and it EXISTS, so refusing with
// not_found would be a lie; the contract's word for it is unsupported.
const auto device = component.asPtrOrNull<IDevice>();

// IDevice::lock() takes no user. openDAQ's other overload,
// IDevicePrivate::lock(IUser*), records who locked it and permits only
// that user to unlock; this host builds a local Instance with no
// authentication, so the lock is anonymous and any later caller may
// undo it. A device already locked by a DIFFERENT user answers
// OPENDAQ_ERR_DEVICE_LOCKED, which this host's closed-set mapping turns
// into read_only -- the refusal the contract names for this row.
device.lock();

// IDevice::unlock() answers OPENDAQ_ERR_ACCESSDENIED when another
// user holds the lock, and that becomes read_only. That refusal is
// precisely the signal a client turns into the offer to force, so
// force is a parameter of this same row rather than a row of its
// own. A device locked anonymously, as this host locks it, unlocks
// here without any force at all.
device.unlock();

// The forced unlock is not on IDevice at all. It is
// IDevicePrivate::forceUnlock(), reached by an interface query, and
// it drops the lock whoever holds it. A build that cannot reach
// IDevicePrivate raises OPENDAQ_ERR_NOINTERFACE here, which the
// closed-set mapping turns into unsupported -- the exact code the
// contract names for a host that cannot serve force: true.
device.asPtr<IDevicePrivate>().forceUnlock();

device.lock.rust:
// openDAQ has no "kind" attribute: a component's kind is whichever of the
// component interfaces it can be cast to, most-derived first, because a
// Channel is also a FunctionBlock and a Device is also a Folder. The
// opendaq crate does that probe once in BaseObject::component_kind(),
// which is Rust's spelling of the C++ host's chain of asPtrOrNull casts.
let kind = component.as_base_object().component_kind();
let wire_kind = match kind {
    Some(ComponentKind::Channel) => "channel",
    Some(ComponentKind::Device) => "device",
    Some(ComponentKind::FunctionBlock) => "function_block",
    Some(ComponentKind::Signal) => "signal",
    // Everything else -- input ports, folders and plain components such as
    // Synchronization -- is reported as a folder; the contract's kind set
    // has no other container.
    _ => "folder",
};

// openDAQ declares isLocked(), lock(), unlock(),
// getAvailableOperationModes() and setOperationMode() on IDevice and not
// on IComponent, so a component has to be queried for its Device
// interface before any of them can be called. A Device is also a Folder
// and a Component, but the reverse does not hold, which is why this is a
// query and not a reinterpretation.
let device = component.as_base_object().try_cast::<Device>();

// IDevice.lock() takes no arguments: it locks for whichever user the
// session authenticated as, and openDAQ then permits an unlock only by
// that same user. The two-argument form, IDevicePrivate.lock(user),
// names a user explicitly and is not what a client calls.
let locked = device.lock();

// IDevice.unlock() refuses with OPENDAQ_ERR_ACCESSDENIED when another
// user holds the lock -- device.h says only the user who locked it may
// unlock it. The closed-set table maps that to read_only, which is the
// exact signal a client turns into the force-unlock control.
let unlocked = device.unlock();

// A forced unlock is not on IDevice at all: openDAQ puts it on
// IDevicePrivate, a separate interface the device has to be queried
// for. That is why the contract's `force` is a parameter and not a
// second row -- the same act on the same node -- and why a device
// that does not carry IDevicePrivate can only answer unsupported.
let private = device.as_base_object().try_cast::<DevicePrivate>();

let forced = private.force_unlock();

